select count(distinct(credit_code)) from risk_control_opinion_monitor
where risk_type = 1 and create_time > curdate() and
credit_code not in (select distinct(credit_code) from risk_control_warn_monitor where risk_type = 1 and data_time < curdate());

SELECT
    id,
    title,
    credit_code,
    info_publ_date
FROM risk_control_opinion_monitor
WHERE

    (
    title = #{param.title}
    AND credit_code = #{param.creditCode}
    AND info_publ_date = #{param.infoPublDate}
    )
